    {

           using var activity =  StartCallActivity("DeleteFileAsync", typeof(DeleteFile).FullName ?? "DeleteFileAsync");

           try
           {
             return client.DeleteFileAsync(fileId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
